// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(address actor, uint256 unlockTime, uint256 warp) public {
        vm.assume(actor != address(0));
        warp = bound(warp, 1, 1e12);
        unlockTime = bound(unlockTime, 0, 1e12);
        vm.warp(warp);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 1}(unlockTime);
        (uint256 accUnlockTime, ) = c.Acc(actor);
        uint256 expected = unlockTime > block.timestamp ? unlockTime : block.timestamp;
        assertTrue(accUnlockTime == expected);
    }
}
